    public ResponseEntity<CancellationPreviewResponse> getCancellationPreview(
        @Parameter(hidden = true) Principal principal,
        // 예약 식별자. 가정: reservationId라는 필수 1~64자 opaque 문자열로 받아 저장소 형식을 노출하지 않는다.
        @Parameter(description = "예약 식별자. 가정: reservationId라는 필수 1~64자 opaque 문자열로 받아 저장소 형식을 노출하지 않는다.", required = true, schema = @Schema(type = "string", minLength = 1, maxLength = 64), example = "rsv_1")
        @PathVariable("reservationId") @NotBlank @Size(min = 1, max = 64) String reservationId) {
        if (principal == null) {
            throw new UnauthenticatedException("UNAUTHENTICATED", "로그인이 필요합니다.");
        }
        return ResponseEntity.ok(service.getCancellationPreview(principal.getName(), reservationId));
    }

